param(
 [Parameter(Mandatory=$true)][string]$RunDirectory,[Parameter(Mandatory=$true)][int]$ProcessId,[Parameter(Mandatory=$true)][long]$WindowHandle,
 [Parameter(Mandatory=$true)][string]$OwnerStatePath,[Parameter(Mandatory=$true)][string]$DocumentName,[Parameter(Mandatory=$true)][string]$TaskSpecPath,
 [Parameter(Mandatory=$true)][string]$LoadSmokeCommandPath,[Parameter(Mandatory=$true)][string]$LoadSmokeReceiptPath,[Parameter(Mandatory=$true)][string]$LoadSmokeBundlePath,
 [Parameter(Mandatory=$true)][string]$GenerationCommandPath,[Parameter(Mandatory=$true)][string]$LoadReceiptPath,[Parameter(Mandatory=$true)][string]$SemanticCommandPath,[Parameter(Mandatory=$true)][string]$SemanticLoadReceiptPath,[Parameter(Mandatory=$true)][string]$GenerationDllSha256,[Parameter(Mandatory=$true)][string]$ScalarDllSha256,[Parameter(Mandatory=$true)][string]$PreviewDllSha256,[Parameter(Mandatory=$true)][string]$CorePreloadManifestPath,[Parameter(Mandatory=$true)][string]$PreviewPreloadManifestPath,
 [Parameter(Mandatory=$true)][string]$GenerationBundlePath,[Parameter(Mandatory=$true)][string]$SemanticBundlePath,[int]$ExpectedCapacityReplacementCount=-1,[int]$ExpectedProvisionalSemanticRank1Count=1,[int]$TimeoutSeconds=120,[string]$PythonPath=$(if($env:CAD_PYTHON){[IO.Path]::GetFullPath($env:CAD_PYTHON)}else{(Get-Command python.exe -CommandType Application -ErrorAction Stop).Source})
)
$ErrorActionPreference='Stop'
$root=[IO.Path]::GetFullPath((Join-Path $PSScriptRoot '../../..'));$run=[IO.Path]::GetFullPath($RunDirectory)
$smokeBundle=[IO.Path]::GetFullPath($LoadSmokeBundlePath);$smokeCommand=[IO.Path]::GetFullPath($LoadSmokeCommandPath);$smokeReceipt=[IO.Path]::GetFullPath($LoadSmokeReceiptPath)
$bundle=[IO.Path]::GetFullPath($GenerationBundlePath);$semanticBundle=[IO.Path]::GetFullPath($SemanticBundlePath)
$observer=[IO.Path]::GetFullPath((Join-Path ([IO.Path]::GetFullPath((Join-Path $PSScriptRoot '../../..'))) 'scripts/cad_command_observer_signal_v1.lsp'))
$commandBuilder=[IO.Path]::GetFullPath((Join-Path ([IO.Path]::GetFullPath((Join-Path $PSScriptRoot '../../..'))) 'scripts/build_inline_observed_cad_command_v3.ps1'))
$sender=[IO.Path]::GetFullPath((Join-Path ([IO.Path]::GetFullPath((Join-Path $PSScriptRoot '../../..'))) 'scripts/cad_rot_send_command_observed_v12.ps1'))
$controller=[IO.Path]::GetFullPath((Join-Path ([IO.Path]::GetFullPath((Join-Path $PSScriptRoot '../../..'))) 'reference/project-orchestration/scripts/invoke_clean_full_generation_semantic_probe_v30.ps1'))
$watcher=[IO.Path]::GetFullPath((Join-Path ([IO.Path]::GetFullPath((Join-Path $PSScriptRoot '../../..'))) 'reference/project-orchestration/scripts/watch_tianzheng_dialogs.ps1'))
foreach($path in @($run,$smokeBundle,$smokeCommand,$smokeReceipt,$bundle,$semanticBundle,$observer,$commandBuilder,$sender,$controller,$watcher)){if(-not$path.StartsWith($root+[IO.Path]::DirectorySeparatorChar,[StringComparison]::OrdinalIgnoreCase)){throw 'SEMANTIC_PROBE_TRUSTED_V31_PATH'}}
foreach($path in @($smokeBundle,$smokeCommand,$bundle,$semanticBundle,$observer,$commandBuilder,$sender,$controller,$watcher)){if(-not(Test-Path -LiteralPath $path -PathType Leaf)){throw 'SEMANTIC_PROBE_TRUSTED_V31_DEPENDENCY'}}
if(Test-Path -LiteralPath $smokeReceipt){throw 'SEMANTIC_PROBE_TRUSTED_V31_SMOKE_RECEIPT_EXISTS'}
$trustedPaths=@($observer,$smokeBundle,$bundle,$semanticBundle);$trustedHashes=@($trustedPaths|ForEach-Object{(Get-FileHash -LiteralPath $_ -Algorithm SHA256).Hash})
$dialogLog=Join-Path $run 'trusted_script_dialogs.jsonl';if(Test-Path -LiteralPath $dialogLog){throw 'SEMANTIC_PROBE_TRUSTED_V31_DIALOG_LOG_EXISTS'}
$dialogJob=Start-Job -ScriptBlock {param($Watcher,$OwnedProcessId,$Log,$Paths,$Hashes,$Title,$TrustedRoot,$WatchTimeout);Set-ExecutionPolicy -Scope Process -ExecutionPolicy Bypass -Force;&$Watcher -ProcessId $OwnedProcessId -LogPath $Log -ExpectedTrustedScriptPaths $Paths -ExpectedTrustedScriptSha256s $Hashes -TrustedScriptRoot $TrustedRoot -MaxTrustedScriptAutoDismissCount $Paths.Count -RequiredMainTitle $Title -TimeoutSeconds $WatchTimeout -QuietSeconds 0} -ArgumentList $watcher,$ProcessId,$dialogLog,$trustedPaths,$trustedHashes,$DocumentName,$root,([Math]::Max(180,$TimeoutSeconds*3))
try{
 $smokeProgress=Join-Path $run 'load_smoke_progress.tsv';$smokeObserved=Join-Path $run 'load_smoke_observed_command.txt'
 $null=&$commandBuilder -BusinessCommandPath $smokeCommand -ProgressPath $smokeProgress -OutputPath $smokeObserved
 $smokeClock=[Diagnostics.Stopwatch]::StartNew();$smokeObservation=&$sender -DocumentName $DocumentName -CommandPath $smokeObserved -ProcessId $ProcessId -WindowHandle $WindowHandle -OwnerStatePath $OwnerStatePath -ProgressPath $smokeProgress -ObservationDirectory (Join-Path $run 'load_smoke_observation') -DocumentBindTimeoutSeconds 12 -StartAckTimeoutSeconds 25 -CommandCompletionTimeoutSeconds $TimeoutSeconds;$smokeClock.Stop()
 if(-not(Test-Path -LiteralPath $smokeReceipt -PathType Leaf)-or([IO.File]::ReadAllText($smokeReceipt,[Text.Encoding]::UTF8).Trim())-cne'LOAD_OK'){throw 'SEMANTIC_PROBE_TRUSTED_V31_LOAD_SMOKE_FAILED'}
 $result=&$controller -RunDirectory $run -ProcessId $ProcessId -WindowHandle $WindowHandle -OwnerStatePath $OwnerStatePath -DocumentName $DocumentName -TaskSpecPath $TaskSpecPath -GenerationCommandPath $GenerationCommandPath -LoadReceiptPath $LoadReceiptPath -SemanticCommandPath $SemanticCommandPath -SemanticLoadReceiptPath $SemanticLoadReceiptPath -GenerationDllSha256 $GenerationDllSha256 -ScalarDllSha256 $ScalarDllSha256 -PreviewDllSha256 $PreviewDllSha256 -CorePreloadManifestPath $CorePreloadManifestPath -PreviewPreloadManifestPath $PreviewPreloadManifestPath -ExpectedCapacityReplacementCount $ExpectedCapacityReplacementCount -ExpectedProvisionalSemanticRank1Count $ExpectedProvisionalSemanticRank1Count -TimeoutSeconds $TimeoutSeconds -PythonPath $PythonPath
 if($dialogJob.State-eq'Failed'){$failure=(Receive-Job -Job $dialogJob -ErrorAction SilentlyContinue 2>&1|Out-String);throw ('SEMANTIC_PROBE_TRUSTED_V31_WATCHER='+$failure)}
 $events=if(Test-Path -LiteralPath $dialogLog){@(Get-Content -LiteralPath $dialogLog -Encoding UTF8)}else{@()}
 [pscustomobject]@{status=[string]$result.status;load_smoke_status='PASS';load_smoke_send_count=1;load_smoke_business_mutation_count=0;load_smoke_elapsed_ms=[int]$smokeClock.ElapsedMilliseconds;transport='ACTIVEX_SENDCOMMAND_EXACT_DOCUMENT_NONFOCUS_ISOLATED';trusted_script_count=$trustedPaths.Count;trusted_script_dialog_event_count=$events.Count;trusted_script_dialog_log=$dialogLog;controller_result=$result}
}finally{if($null-ne$dialogJob){if($dialogJob.State-eq'Running'){Stop-Job -Job $dialogJob -ErrorAction SilentlyContinue};Receive-Job -Job $dialogJob -ErrorAction SilentlyContinue|Out-Null;Remove-Job -Job $dialogJob -Force -ErrorAction SilentlyContinue}}
